import React, { useEffect, useState, useCallback } from 'react';
import { View, ScrollView, RefreshControl, StyleSheet, ActivityIndicator, Alert, SafeAreaView, Platform, StatusBar as RNStatusBar } from 'react-native';
import { useNavigation } from '@react-navigation/native';
import api from '../services/api';

// Components
import Header from '../components/Header';
import Banner from '../components/Banner';
import VideoFeed from '../components/VideoFeed';
import ProductList from '../components/ProductList';
import SectionHeader from '../components/SectionHeader';

interface Product {
  id: string;
  name: string;
  price: number;
  oldPrice?: number;
  description: string;
  image?: string;
  images?: { url: string }[];
  videoUrl?: string; // Optional field if backend supports it
  rating?: number;
  discount?: number;
}

const HomeScreen = () => {
  const navigation = useNavigation<any>();
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [products, setProducts] = useState<Product[]>([]);
  const [bannerItem, setBannerItems] = useState<Product[]>([]);
  const [videoItems, setVideoItems] = useState<Product[]>([]);

  const fetchData = async () => {
    try {
      // In a real app with separate endpoints, you'd do Promise.all([api.get('/banners'), api.get('/products')...])
      // Here we assume /products returns everything we need or we filter from it.
      const response = await api.get('/products');
      const allProducts: Product[] = response.data.products || response.data || [];

      if (!Array.isArray(allProducts)) {
         throw new Error("Invalid data format");
      }

      setProducts(allProducts);

      // Simulate deriving sections from the main list if specific endpoints don't exist
      // 1. Banner: Take first 5 or random 5
      const bannerSlice = allProducts.slice(0, 5).map(p => ({
        ...p,
        // Calculate discount if not present, purely for UI show
        discount: p.oldPrice && p.price ? Math.round(((p.oldPrice - p.price) / p.oldPrice) * 100) : 10 // Mock discount
      }));
      setBannerItems(bannerSlice);

      // 2. Videos: items with 'videoUrl' or just some items to populate the feed
      const videoSlice = allProducts.filter(p => p.videoUrl).length > 0 
          ? allProducts.filter(p => p.videoUrl) 
          : allProducts.slice(5, 10); // Fallback to next 5 items
      setVideoItems(videoSlice);

    } catch (error) {
      console.error('Error fetching data:', error);
      // Fallback empty state is better than crash, but user requested DB data.
      // We will show empty if API fails, or maybe an alert.
      // Alert.alert('Error', 'Failed to load products from server.');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const onRefresh = useCallback(() => {
    setRefreshing(true);
    fetchData();
  }, []);

  const handleProductPress = (item: Product) => {
    navigation.navigate('ProductDetail', { productId: item.id });
  };

  if (loading) {
    return (
      <View style={styles.center}>
        <ActivityIndicator size="large" color="#E53935" />
      </View>
    );
  }

  return (
    <SafeAreaView style={styles.safeArea}>
      <View style={styles.container}>
        <Header />
        <ScrollView 
          contentContainerStyle={styles.scrollContent}
          refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} />}
        >
          {/* Banners */}
          <Banner data={bannerItem} onPress={handleProductPress} />

          {/* Video Feed Section */}
          {videoItems.length > 0 && (
            <>
              <SectionHeader title="Trending Videos" onSeeAll={() => {}} />
              <VideoFeed data={videoItems} onPress={handleProductPress} />
            </>
          )}

          {/* All Products Section */}
          <SectionHeader title="New Arrivals" />
          <ProductList data={products} onPress={handleProductPress} />
          
        </ScrollView>
      </View>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  safeArea: {
    flex: 1,
    backgroundColor: '#fff',
    paddingTop: Platform.OS === 'android' ? RNStatusBar.currentHeight : 0,
  },
  container: {
    flex: 1,
    backgroundColor: '#fff',
  },
  center: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
  },
  scrollContent: {
    paddingBottom: 20,
  },
});

export default HomeScreen;
